SELECT tuning_id AS tuningId, base_task_id AS baseTaskId, MAX(project_id) AS projectId, MAX(search_method) AS searchMethod, COUNT(*) AS trialCount, MAX(accuracy) AS bestAccuracy, SUM(applied) AS appliedCount, MIN(create_date) AS createDate FROM federated_learning_tuning WHERE is_del = 0
AND project_id = #{projectId}
AND base_task_id = #{baseTaskId}
GROUP BY tuning_id, base_task_id ORDER BY MIN(create_date) DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT tuning_id)
FROM federated_learning_tuning
WHERE is_del = 0

    AND project_id = #{projectId}


    AND base_task_id = #{baseTaskId}
